"""The orders page: a table of orders and two buttons."""
from csv_export import to_csv


class OrdersPage:
    def __init__(self, orders):
        self.orders = list(orders)
        self.shown = []
        self.downloads = []
        self._handlers = {}
        self._on("refresh", self.refresh)

    def _on(self, button, handler):
        self._handlers[button] = handler

    def click(self, button):
        """Run the button's handler. A button with no handler does nothing."""
        handler = self._handlers.get(button)
        if handler:
            handler()

    def refresh(self):
        self.shown = sorted(self.orders, key=lambda order: order["id"])

    def export(self):
        self.downloads.append(to_csv(self.orders))
"""Runs once a night and counts the day's payments that match no order."""


class ReconciliationWorker:
    def __init__(self, store):
        self.store = store

    def run(self, day):
        """Return how many of the day's payments match no order."""
        order_ids = self.store.order_ids()
        unmatched = [payment for payment in self.store.payments(day) if payment["order_id"] not in order_ids]
        return len(unmatched)
"""The nightly job: count the day's payments that match no order."""


def run_nightly_job(store, day):
    order_ids = store.order_ids()
    return len([payment for payment in store.payments(day) if payment["order_id"] not in order_ids])
